#!/usr/bin/env node
/**
 * Build-time credential injection (Electron equivalent of the Wails ldflags).
 *
 * Reads GMAPS_SUPABASE_URL / GMAPS_SUPABASE_ANON_KEY from app/.env and
 * generates src/main/build-config.ts so the packaged app ships with the
 * license backend configured. Writes empty values when no .env exists, so
 * fresh clones still compile (the app then reports "License system not
 * configured" until credentials are provided).
 *
 * The generated file is gitignored — never commit secrets.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const ENV_CANDIDATES = [path.join(root, ".env")];

function parseEnv(file) {
  const out = {};
  const text = fs.readFileSync(file, "utf8");
  for (const line of text.split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
    if (!m) continue;
    let value = m[2];
    // Strip surrounding quotes if present.
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    out[m[1]] = value;
  }
  return out;
}

let env = {};
let source = null;
for (const candidate of ENV_CANDIDATES) {
  if (fs.existsSync(candidate)) {
    env = parseEnv(candidate);
    source = candidate;
    break;
  }
}

const url = env.GMAPS_SUPABASE_URL || "";
const key = env.GMAPS_SUPABASE_ANON_KEY || "";

const content = `// AUTO-GENERATED by scripts/inject-build-config.mjs — do not edit, do not commit.
// Source: ${source ? path.relative(root, source) : "no .env found (empty values)"}
export const BUILD_SUPABASE_URL = ${JSON.stringify(url)};
export const BUILD_SUPABASE_ANON_KEY = ${JSON.stringify(key)};
`;

const target = path.join(root, "src", "main", "build-config.ts");
fs.writeFileSync(target, content, "utf8");

if (url && key) {
  console.log(`[inject-build-config] credentials embedded from ${path.relative(root, source)}`);
} else {
  console.warn("[inject-build-config] WARNING: no Supabase credentials found — license system will be disabled.");
}
